const webhookData = $('1. Webhook').item.json;
const headers = webhookData.headers || {};
const tenantId = headers['x-tenant-id'] || '00000000-0000-0000-0000-000000000001';
const documentId = headers['x-document-id'] || '';
const knowledgeBaseId = headers['x-knowledge-base-id'] || '';
const gdriveFolder = headers['x-gdrive-folder'] || 'Biokool';
const driveResult = $('2. Google Drive').item.json;

return [{
  json: {
    documentId,
    tenantId,
    knowledgeBaseId,
    gdriveFolder,
    gdriveFileId: driveResult.id || '',
    gdriveFileName: driveResult.name || '',
    timestamp: new Date().toISOString()
  }
}];

const metadata = $('3. Metadata').item.json;
const driveResult = $('2. Google Drive').item.json;
const versionResult = $('4b. Save Version').item.json;

return [{
  json: {
    success: true,
    documentId: metadata.documentId,
    tenantId: metadata.tenantId,
    filename: driveResult.name || '',
    fileUrl: 'https://drive.google.com/file/d/' + metadata.gdriveFileId + '/view',
    storageProvider: 'gdrive',
    version: versionResult ? versionResult.version_number : 1,
    versionId: versionResult ? versionResult.id : null,
    gdriveFileId: metadata.gdriveFileId,
    gdriveFolder: metadata.gdriveFolder,
    timestamp: new Date().toISOString(),
    message: 'Archivo subido a Google Drive y version registrada'
  }
}];
